bool check(int num, int currnum, int target) {
    if (currnum > target) return false;
    if (num == 0) return currnum == target;
    static std::map<std::tuple<int,int,int>, bool> memo;
    auto key = std::make_tuple(num, currnum, target);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    bool res = check(num / 10, currnum + num % 10, target) ||
               check(num / 100, currnum + num % 100, target) ||
               check(num / 1000, currnum + num % 1000, target) ||
               check(num / 10000, currnum + num % 10000, target);
    memo[key] = res;
    return res;
}

