int LIS(vector<int>& nums, int i, int prev, int mod) {
        if(i >= nums.size()) {
            return 0;
        }

        int take = 0;
        int skip = 0;

        //take
        if(prev == -1 || (nums[prev] + nums[i])%2 == mod) {
            take = 1 + LIS(nums, i+1, i, mod);
        }

        //skip
        skip = LIS(nums, i+1, prev, mod);

        return max(take, skip);
    }

