int LIS(vector<int>& nums, int i, int prev, int mod) {
    if (i >= (int)nums.size()) return 0;

    static vector<vector<int>> memo;
    static const int* lastPtr = nullptr;
    static int lastMod = -2;

    if (i == 0 && prev == -1) {
        if (nums.data() != lastPtr || lastMod != mod) {
            memo.assign(nums.size(), vector<int>(nums.size() + 1, -1));
            lastPtr = nums.data();
            lastMod = mod;
        }
    }

    int pIdx = prev + 1; // -1 -> 0
    if (pIdx >= 0 && i < (int)memo.size() && pIdx < (int)memo[i].size() && memo[i][pIdx] != -1) {
        return memo[i][pIdx];
    }

    int take = 0;
    if (prev == -1 || (nums[prev] + nums[i]) % 2 == mod) {
        take = 1 + LIS(nums, i + 1, i, mod);
    }
    int skip = LIS(nums, i + 1, prev, mod);
    int res = max(take, skip);

    if (i < (int)memo.size() && pIdx < (int)memo[i].size()) {
        memo[i][pIdx] = res;
    }
    return res;
}
